{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7892.md",
  "title": "EIP-7892: Blob Parameter Only Hardforks",
  "category": "EIP",
  "type": "Informational",
  "status": "Final",
  "layer": "consensus+execution",
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "BPO Hardfork Definition",
      "description": "Defines BPO (Blob Parameter Only) hardforks as protocol upgrades that modify only blob-related parameters through configuration, without requiring any client-side code changes. New parameters take effect immediately at the specified activation time.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "BPO hardforks MUST NOT require any client-side code changes; they are configuration-only upgrades."
        },
        {
          "id": "INV-002",
          "text": "New blob parameters take effect immediately at the specified activation time."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [],
      "postconditions": [],
      "references": {
        "requires": ["EIP-7840"]
      }
    },
    {
      "id": "SG-002",
      "name": "Blob Schedule Configuration",
      "description": "Defines the three protocol parameters managed by the blob schedule configuration: target (expected blobs per block), max (maximum blobs per block), and baseFeeUpdateFraction (blob gas pricing adjustment factor).",
      "invariants": [
        {
          "id": "INV-003",
          "text": "When a regular hardfork changes any blob parameters, it MUST do so by adding an entry to the blob schedule configuration."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-001",
          "name": "target",
          "type": "integer",
          "description": "The expected number of blobs per block (Blob Target)."
        },
        {
          "id": "SV-002",
          "name": "max",
          "type": "integer",
          "description": "The maximum number of blobs per block (Blob Limit)."
        },
        {
          "id": "SV-003",
          "name": "baseFeeUpdateFraction",
          "type": "integer",
          "description": "Determines how blob gas pricing adjusts per block (Blob Base Fee Update Fraction)."
        }
      ],
      "data_structures": [
        {
          "id": "DS-001",
          "name": "BlobSchedule",
          "type": "class",
          "language": "python",
          "fields": [
            {"name": "target", "type": "U64"},
            {"name": "max", "type": "U64"},
            {"name": "base_fee_update_fraction", "type": "Uint"}
          ],
          "source": "class BlobSchedule:\n   target: U64\n   max: U64\n   base_fee_update_fraction: Uint"
        }
      ],
      "preconditions": [],
      "postconditions": []
    },
    {
      "id": "SG-003",
      "name": "Execution Layer Configuration",
      "description": "Specifies how BPO forks are configured on the execution layer. Each fork in the blobSchedule object (defined in EIP-7840) is linked to an activation timestamp via a top-level <fork_name>Time field holding the Unix timestamp as a JSON number. BPO forks use the naming convention bpo<index> starting at 1. Activation timestamps are only required for forks after Prague.",
      "invariants": [
        {
          "id": "INV-004",
          "text": "BPO forks SHOULD be named using the convention 'bpo<index>', where <index> starts at 1."
        },
        {
          "id": "INV-005",
          "text": "Activation timestamps are required only for forks that occur after Prague."
        },
        {
          "id": "INV-006",
          "text": "Since there is no backporting, the values for cancunTime and pragueTime are set to 0."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-002",
          "name": "EL blobSchedule JSON",
          "type": "json_config",
          "language": "json",
          "description": "Top-level JSON configuration containing a blobSchedule object mapping fork names to blob parameter objects, plus <fork_name>Time fields for activation timestamps.",
          "example": {
            "blobSchedule": {
              "cancun": {"target": 3, "max": 6, "baseFeeUpdateFraction": 3338477},
              "prague": {"target": 6, "max": 9, "baseFeeUpdateFraction": 5007716},
              "osaka": {"target": 6, "max": 9, "baseFeeUpdateFraction": 5007716},
              "bpo1": {"target": 10, "max": 15, "baseFeeUpdateFraction": 8346193},
              "bpo2": {"target": 14, "max": 21, "baseFeeUpdateFraction": 11684671}
            },
            "cancunTime": 0,
            "pragueTime": 0,
            "osakaTime": 1747387400,
            "bpo1Time": 1757387400,
            "bpo2Time": 1767387784
          }
        }
      ],
      "preconditions": [],
      "postconditions": [],
      "references": {
        "requires": ["EIP-7840"]
      }
    },
    {
      "id": "SG-004",
      "name": "Blob Base Fee Computations",
      "description": "Modifies the functions get_base_fee_per_blob_gas and calc_excess_blob_gas (originally from EIP-4844) to explicitly use the blob schedule. The current block's blob schedule is used (consistent with EIP-7691). TARGET_BLOB_GAS_PER_BLOCK is removed and replaced with GAS_PER_BLOB * blob_schedule.target.",
      "invariants": [
        {
          "id": "INV-007",
          "text": "TARGET_BLOB_GAS_PER_BLOCK is removed and replaced with GAS_PER_BLOB * blob_schedule.target."
        },
        {
          "id": "INV-008",
          "text": "The functions use the current block's blob schedule for computations (consistent with EIP-7691 handling)."
        }
      ],
      "functions": [
        {
          "id": "FN-001",
          "name": "calc_excess_blob_gas",
          "signature": "def calc_excess_blob_gas(parent: Header, blob_schedule: BlobSchedule) -> int",
          "parameters": [
            {"name": "parent", "type": "Header", "description": "The parent block header."},
            {"name": "blob_schedule", "type": "BlobSchedule", "description": "The current block's blob schedule parameters."}
          ],
          "return_type": "int",
          "description": "Calculates excess blob gas for the current block. Computes target_blob_gas as GAS_PER_BLOB * blob_schedule.target. Returns 0 if (parent.excess_blob_gas + parent.blob_gas_used) < target_blob_gas, otherwise returns the difference.",
          "state_transitions": [
            {
              "id": "ST-001",
              "description": "If parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas, excess resets to 0.",
              "from_state": "parent block header with excess_blob_gas and blob_gas_used",
              "to_state": "excess_blob_gas = 0"
            },
            {
              "id": "ST-002",
              "description": "If parent.excess_blob_gas + parent.blob_gas_used >= target_blob_gas, excess is the surplus above target.",
              "from_state": "parent block header with excess_blob_gas and blob_gas_used",
              "to_state": "excess_blob_gas = parent.excess_blob_gas + parent.blob_gas_used - target_blob_gas"
            }
          ],
          "source": "def calc_excess_blob_gas(parent: Header, blob_schedule: BlobSchedule) -> int:\n    target_blob_gas = GAS_PER_BLOB * blob_schedule.target\n    if parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas :\n        return 0\n    else:\n        return parent.excess_blob_gas + parent.blob_gas_used - target_blob_gas"
        },
        {
          "id": "FN-002",
          "name": "get_base_fee_per_blob_gas",
          "signature": "def get_base_fee_per_blob_gas(header: Header, blob_schedule: BlobSchedule) -> int",
          "parameters": [
            {"name": "header", "type": "Header", "description": "The current block header."},
            {"name": "blob_schedule", "type": "BlobSchedule", "description": "The current block's blob schedule parameters."}
          ],
          "return_type": "int",
          "description": "Calculates the base fee per blob gas using the fake_exponential function with MIN_BASE_FEE_PER_BLOB_GAS, the header's excess_blob_gas, and the blob_schedule's base_fee_update_fraction.",
          "source": "def get_base_fee_per_blob_gas(header: Header, blob_schedule: BlobSchedule) -> int:\n    return fake_exponential(\n        MIN_BASE_FEE_PER_BLOB_GAS,\n        header.excess_blob_gas,\n        blob_schedule.base_fee_update_fraction\n    )"
        }
      ],
      "state_variables": [
        {
          "id": "SV-004",
          "name": "GAS_PER_BLOB",
          "type": "constant",
          "description": "Gas consumed per blob (inherited from EIP-4844)."
        },
        {
          "id": "SV-005",
          "name": "MIN_BASE_FEE_PER_BLOB_GAS",
          "type": "constant",
          "description": "Minimum base fee per blob gas (inherited from EIP-4844)."
        }
      ],
      "data_structures": [],
      "preconditions": [
        {
          "id": "PRE-001",
          "text": "A valid BlobSchedule must be determined for the current block before calling these functions."
        }
      ],
      "postconditions": [
        {
          "id": "POST-001",
          "text": "calc_excess_blob_gas returns a non-negative integer (0 or the excess above target)."
        },
        {
          "id": "POST-002",
          "text": "get_base_fee_per_blob_gas returns a fee computed via fake_exponential, always >= MIN_BASE_FEE_PER_BLOB_GAS."
        }
      ],
      "references": {
        "modifies": ["EIP-4844"],
        "consistent_with": ["EIP-7691"]
      }
    },
    {
      "id": "SG-005",
      "name": "Consensus Layer Configuration",
      "description": "Defines the BLOB_SCHEDULE field in the consensus layer configuration, containing a sequence of entries representing blob parameter changes after ELECTRA_FORK_EPOCH. There is one entry per fork that changes blob parameters, whether regular or BPO.",
      "invariants": [
        {
          "id": "INV-009",
          "text": "Execution and consensus clients MUST share consistent BPO fork schedules."
        },
        {
          "id": "INV-010",
          "text": "The slot number in the EL's blobSchedule MUST align with the start of the epoch specified in the consensus layer configuration."
        },
        {
          "id": "INV-011",
          "text": "The 'max' field in the EL's blobSchedule MUST equal the MAX_BLOBS_PER_BLOCK value in the consensus layer configuration."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-006",
          "name": "BLOB_SCHEDULE",
          "type": "Sequence[BlobScheduleEntry]",
          "description": "Consensus layer configuration field containing blob parameter change entries after ELECTRA_FORK_EPOCH."
        }
      ],
      "data_structures": [
        {
          "id": "DS-003",
          "name": "CL BLOB_SCHEDULE YAML",
          "type": "yaml_config",
          "language": "yaml",
          "description": "Consensus layer configuration for blob schedule with EPOCH and MAX_BLOBS_PER_BLOCK per entry.",
          "example_yaml": "BLOB_SCHEDULE:\n  - EPOCH: 400000\n    MAX_BLOBS_PER_BLOCK: 15\n  - EPOCH: 420000\n    MAX_BLOBS_PER_BLOCK: 21"
        }
      ],
      "preconditions": [],
      "postconditions": []
    },
    {
      "id": "SG-006",
      "name": "Modified compute_fork_digest",
      "description": "Updates the compute_fork_digest helper to account for BPO forks by XOR-bitmasking the max_blobs_per_block parameter into the base 4-byte fork digest. This ensures that peers on different blob schedules produce different fork digests, enabling correct peer discovery and gossip topic rotation.",
      "invariants": [
        {
          "id": "INV-012",
          "text": "max_blobs_per_block MUST fit within a 32-bit unsigned integer (0 <= max_blobs_per_block <= 0xFFFFFFFF)."
        },
        {
          "id": "INV-013",
          "text": "If no blob schedule entry applies to the current epoch (blob_params is None), the base digest is returned unchanged."
        }
      ],
      "functions": [
        {
          "id": "FN-003",
          "name": "compute_fork_digest",
          "signature": "def compute_fork_digest(current_version: Version, genesis_validators_root: Root, current_epoch: Epoch, blob_schedule: Sequence[BlobScheduleEntry]) -> ForkDigest",
          "parameters": [
            {"name": "current_version", "type": "Version", "description": "The baseline hardfork version atop which the blob schedule is applied (unchanged from original)."},
            {"name": "genesis_validators_root", "type": "Root", "description": "Genesis validators root for domain separation (unchanged from original)."},
            {"name": "current_epoch", "type": "Epoch", "description": "The current epoch used to look up the applicable blob schedule entry (new parameter)."},
            {"name": "blob_schedule", "type": "Sequence[BlobScheduleEntry]", "description": "The full blob schedule sequence to determine current blob parameters (new parameter)."}
          ],
          "return_type": "ForkDigest",
          "description": "Returns the 4-byte fork digest for the current_version and genesis_validators_root, bitmasking blob parameters after ELECTRA_FORK_VERSION. The function computes the base digest, finds the applicable blob schedule entry for the current epoch, and XORs max_blobs_per_block (as 4 big-endian bytes) into the base digest.",
          "state_transitions": [
            {
              "id": "ST-003",
              "description": "When no blob schedule entry applies (blob_params is None), the base digest (4 bytes from compute_fork_data_root) is returned directly.",
              "from_state": "No applicable blob schedule for current_epoch",
              "to_state": "ForkDigest = base_digest (unmodified)"
            },
            {
              "id": "ST-004",
              "description": "When a blob schedule entry applies, the digest is XOR-masked with max_blobs_per_block encoded as 4 big-endian bytes.",
              "from_state": "Applicable blob schedule entry found for current_epoch",
              "to_state": "ForkDigest = base_digest XOR max_blobs_per_block.to_bytes(4, 'big')"
            }
          ],
          "source": "def compute_fork_digest(\n  current_version: Version,\n  genesis_validators_root: Root,\n  current_epoch: Epoch,\n  blob_schedule: Sequence[BlobScheduleEntry]\n) -> ForkDigest:\n    base_digest = compute_fork_data_root(current_version, genesis_validators_root)[:4]\n    sorted_schedule = sorted(blob_schedule, key=lambda e: e.epoch, reverse=True)\n    blob_params = None\n    for entry in sorted_schedule:\n      if current_epoch >= entry.epoch:\n        blob_params = entry\n        break\n    if blob_params is None:\n      return ForkDigest(base_digest)\n    assert 0 <= blob_params.max_blobs_per_block <= 0xFFFFFFFF\n    mask = blob_params.max_blobs_per_block.to_bytes(4, 'big')\n    masked_digest = bytes(a ^ b for a, b in zip(base_digest, mask))\n    return ForkDigest(masked_digest)"
        }
      ],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-004",
          "name": "BlobScheduleEntry",
          "type": "dataclass",
          "language": "python",
          "decorator": "@dataclass",
          "fields": [
            {"name": "epoch", "type": "Epoch"},
            {"name": "max_blobs_per_block", "type": "uint64"}
          ],
          "source": "@dataclass\nclass BlobScheduleEntry:\n   epoch: Epoch\n   max_blobs_per_block: uint64"
        }
      ],
      "preconditions": [
        {
          "id": "PRE-002",
          "text": "current_version must be a valid fork version identifier."
        },
        {
          "id": "PRE-003",
          "text": "genesis_validators_root must be the correct root for the chain."
        },
        {
          "id": "PRE-004",
          "text": "blob_schedule entries must have unique, valid epoch values."
        }
      ],
      "postconditions": [
        {
          "id": "POST-003",
          "text": "The returned ForkDigest is exactly 4 bytes."
        },
        {
          "id": "POST-004",
          "text": "Two nodes with identical blob schedules and same current_epoch produce the same fork digest."
        },
        {
          "id": "POST-005",
          "text": "Nodes on different blob schedule entries (different max_blobs_per_block) produce different fork digests (with overwhelming probability)."
        }
      ],
      "references": {
        "modifies": ["compute_fork_digest (existing CL helper)"]
      }
    },
    {
      "id": "SG-007",
      "name": "P2P Networking: ENR Extension",
      "description": "Extends consensus layer ENRs (Ethereum Node Records) with a new 'nfd' (next fork digest) field that communicates the digest of the next scheduled fork, whether regular or BPO. This is agnostic to specific fork types and offers long-term flexibility for peer discovery.",
      "invariants": [
        {
          "id": "INV-014",
          "text": "When discovering and interfacing with peers, nodes MUST evaluate 'nfd' alongside their existing consideration of the ENRForkID::next_* fields under the 'eth2' key."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-007",
          "name": "nfd",
          "type": "SSZ Bytes4 (ForkDigest)",
          "description": "ENR key 'nfd' (next fork digest): communicates the digest of the next scheduled fork in the consensus layer ENR."
        }
      ],
      "data_structures": [
        {
          "id": "DS-005",
          "name": "ENR nfd Entry",
          "type": "enr_field",
          "fields": [
            {"key": "nfd", "value": "SSZ Bytes4 ForkDigest"}
          ]
        }
      ],
      "preconditions": [],
      "postconditions": []
    },
    {
      "id": "SG-008",
      "name": "P2P Networking: Status and Gossip",
      "description": "Clarifies that no changes are needed to the Status req/resp interaction (though the response payload must correctly contain the updated fork_digest). No changes are required to gossip topic structure or configuration; however, all topics automatically rotate at a BPO fork due to changes in their ForkDigestValue component.",
      "invariants": [
        {
          "id": "INV-015",
          "text": "The Status response payload must correctly contain the updated fork_digest after a BPO fork."
        },
        {
          "id": "INV-016",
          "text": "All gossip topics automatically rotate at a BPO fork due to changes in their ForkDigestValue component."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [],
      "postconditions": []
    },
    {
      "id": "SG-009",
      "name": "Cross-Layer Consistency Requirements",
      "description": "Defines the critical consistency constraints between execution layer and consensus layer BPO configurations, ensuring that both layers agree on fork schedules, activation times, and blob limits.",
      "invariants": [
        {
          "id": "INV-017",
          "text": "Execution and consensus clients MUST share consistent BPO fork schedules."
        },
        {
          "id": "INV-018",
          "text": "The slot number in the EL's blobSchedule MUST align with the start of the epoch specified in the consensus layer configuration."
        },
        {
          "id": "INV-019",
          "text": "The 'max' field in the EL's blobSchedule MUST equal the MAX_BLOBS_PER_BLOCK value in the consensus layer configuration."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {
          "id": "PRE-005",
          "text": "Both EL and CL clients must be configured with the same set of BPO fork entries before activation."
        }
      ],
      "postconditions": [
        {
          "id": "POST-006",
          "text": "At any given time, the blob parameters in effect on the EL match those in effect on the CL."
        }
      ]
    }
  ],
