{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7917.md",
  "title": "EIP-7917: Deterministic Proposer Lookahead",
  "category": "EIP",
  "type": "Standards Track / Core",
  "status": "Final",
  "layer": "consensus",
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "BeaconState Extension: Proposer Lookahead Field",
      "description": "Extends the BeaconState container with a new 'proposer_lookahead' field. This field is a fixed-size vector of ValidatorIndex values covering the full visible lookahead period, from the start of the current epoch through the next MIN_SEED_LOOKAHEAD epochs. The vector length is (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH. For example, proposer_lookahead[0] is the proposer for the first slot of the current epoch, and proposer_lookahead[SLOTS_PER_EPOCH + 4] is the proposer for the fifth slot of the next epoch.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "The proposer_lookahead vector MUST always have exactly (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH entries."
        },
        {
          "id": "INV-002",
          "text": "proposer_lookahead[0] MUST correspond to the validator index of the proposer for the first slot of the current epoch."
        },
        {
          "id": "INV-003",
          "text": "Each entry in proposer_lookahead MUST be a valid ValidatorIndex referencing an active validator eligible for proposing in the corresponding epoch."
        },
        {
          "id": "INV-004",
          "text": "proposer_lookahead[SLOTS_PER_EPOCH + k] MUST be the validator index for slot k of the next epoch (for k in 0..SLOTS_PER_EPOCH-1)."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-001",
          "name": "proposer_lookahead",
          "type": "Vector[ValidatorIndex, (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH]",
          "container": "BeaconState",
          "description": "A fixed-size vector storing pre-computed proposer validator indices for the current epoch and the next MIN_SEED_LOOKAHEAD epochs. Indexed positionally so that index i maps to the (i % SLOTS_PER_EPOCH)-th slot of epoch (current_epoch + i // SLOTS_PER_EPOCH)."
        }
      ],
      "data_structures": [
        {
          "id": "DS-001",
          "name": "BeaconState (extended)",
          "type": "class",
          "language": "python",
          "description": "The BeaconState container is extended with a proposer_lookahead field appended to the existing fields.",
          "source": "class BeaconState:\n    ...\n    proposer_lookahead: Vector[ValidatorIndex, (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH]"
        }
      ],
      "preconditions": [],
      "postconditions": [],
      "constants_referenced": [
        {
          "id": "CONST-001",
          "name": "MIN_SEED_LOOKAHEAD",
          "value": "1 (current mainnet value)",
          "description": "The minimum number of epochs of seed lookahead. Determines how far ahead the proposer schedule is pre-computed."
        },
        {
          "id": "CONST-002",
          "name": "SLOTS_PER_EPOCH",
          "value": "32 (current mainnet value)",
          "description": "Number of slots in each epoch. Determines the size of each epoch chunk in the lookahead vector."
        }
      ]
    },
    {
      "id": "SG-002",
      "name": "Proposer Index Lookup (get_beacon_proposer_index)",
      "description": "Replaces the previous on-demand calculation of the beacon proposer index with a simple O(1) lookup into the pre-computed proposer_lookahead vector. Uses (state.slot % SLOTS_PER_EPOCH) as the index into the vector, returning the proposer for the current slot in constant time.",
      "invariants": [
        {
          "id": "INV-005",
          "text": "get_beacon_proposer_index MUST return a valid ValidatorIndex for every slot within the current epoch."
        },
        {
          "id": "INV-006",
          "text": "The returned index MUST correspond to an active validator eligible for proposing at the given slot."
        },
        {
          "id": "INV-007",
          "text": "The function MUST be deterministic: for the same state and slot, it MUST always return the same ValidatorIndex."
        },
        {
          "id": "INV-008",
          "text": "The function is read-only: it MUST NOT modify any state."
        }
      ],
      "functions": [
        {
          "id": "FN-001",
          "name": "get_beacon_proposer_index",
          "signature": "get_beacon_proposer_index(state: BeaconState) -> ValidatorIndex",
          "parameters": [
            {
              "name": "state",
              "type": "BeaconState",
              "description": "The current beacon chain state containing the proposer_lookahead vector."
            }
          ],
          "return_type": "ValidatorIndex",
          "description": "Return the beacon proposer index at the current slot by performing a direct lookup into state.proposer_lookahead using state.slot % SLOTS_PER_EPOCH as the index.",
