      "security_properties": [
        {
          "id": "SEC-001",
          "name": "Effective Balance Grinding Resistance",
          "description": "Validators cannot adjust effective balance after seeing RANDAO to influence the proposer schedule. Before this EIP, effective balances for epoch N's proposer schedule were taken at the start of epoch N, while the RANDAO seed was known at epoch N - MIN_SEED_LOOKAHEAD. This created a window where a validator could grind EB to manipulate the schedule. Now both inputs are frozen at epoch N - MIN_SEED_LOOKAHEAD.",
          "attack_vector": "A validator observes the RANDAO seed for a future epoch and manipulates their effective balance (via slashings, penalties accumulating to >= 1 ETH, consolidations, deposits, or reward accumulation beyond 32 ETH with EIP-7251) to increase their probability of being selected as proposer.",
          "mitigation": "Effective balances used for proposer election are frozen at the same time as the RANDAO seed, eliminating the grinding window entirely."
        },
        {
          "id": "SEC-002",
          "name": "EIP-7251 (MaxEB) Interaction",
          "description": "EIP-7251 increases effective balance unpredictability by allowing EBs to exceed 32 ETH through rewards accumulating to >= 1 ETH, validator consolidations, and deposits. This EIP mitigates the increased attack surface by freezing EBs earlier in the proposer election pipeline.",
          "attack_vector": "With uncapped MaxEB, more frequent effective balance changes (rewards crossing 1 ETH thresholds, validator consolidations) create additional opportunities for proposer schedule manipulation.",
          "mitigation": "The deterministic lookahead pre-computes the schedule before any EB changes can take effect."
        },
        {
          "id": "SEC-003",
          "name": "RANDAO and EB Delay Alignment",
          "description": "Before this EIP, the RANDAO delay and EB delay were misaligned: the RANDAO seed for epoch N was fixed at epoch N - MIN_SEED_LOOKAHEAD - 1, but EBs could change up to the start of epoch N. By aligning both to the same point in time, the possibility of validators adjusting EB after seeing the RANDAO outcome is removed entirely, simplifying security analysis.",
          "attack_vector": "Validators could observe the fixed RANDAO seed and then manipulate their EB within the remaining window before the proposer schedule calculation.",
          "mitigation": "Both RANDAO seeds and effective balances are now fixed at the same epoch boundary, eliminating the manipulation window."
        }
      ]
    },
